#include <vector>
#include <list>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> v = {5, 2, 8};
    std::list<int> l = {1, 9, 3};

    // std::sort requires Random Access Iterators (only works on vector)
    std::sort(v.begin(), v.end()); 

    // std::find works on both (requires Input Iterators)
    auto it_v = std::find(v.begin(), v.end(), 8);
    auto it_l = std::find(l.begin(), l.end(), 9);

    std::cout << "Found 8 in vector at index: " 
              << std::distance(v.begin(), it_v) << std::endl;
}
